-- Primebrick: Job module — job_rule field hints + emitted-event description.
-- The host EntityFormPage archetype renders `MetaColumn.tooltip`/`tooltip_title`
-- via FormLabelWithPriorityHelp (priority HINT); the subject ComboSelect renders
-- `EmitDecl.description_key` as the detailed option label.
-- Convention: `job.entities.job_rule.hints.<column>` / `..._title` and
-- `job.events.*` in job.translations (namespace boundary — `job.*` only).

INSERT INTO job.translations (key, language, value, created_by, updated_by) VALUES
  -- event_subject
  ('job.entities.job_rule.hints.event_subject_title', 'en-GB', 'Event subject', 'initial-setup', 'initial-setup'),
  ('job.entities.job_rule.hints.event_subject_title', 'en-US', 'Event subject', 'initial-setup', 'initial-setup'),
  ('job.entities.job_rule.hints.event_subject_title', 'it-IT', 'Soggetto evento', 'initial-setup', 'initial-setup'),
  ('job.entities.job_rule.hints.event_subject_title', 'de-DE', 'Ereignis-Subject', 'initial-setup', 'initial-setup'),
  ('job.entities.job_rule.hints.event_subject_title', 'fr-FR', 'Sujet de l''événement', 'initial-setup', 'initial-setup'),
  ('job.entities.job_rule.hints.event_subject_title', 'es-ES', 'Asunto del evento', 'initial-setup', 'initial-setup'),
  ('job.entities.job_rule.hints.event_subject_title', 'pt-PT', 'Assunto do evento', 'initial-setup', 'initial-setup'),
  ('job.entities.job_rule.hints.event_subject', 'en-GB', 'The NATS subject this rule listens to — when a module publishes an event on this subject the rule may fire. Pick a declared event or type any subject (wildcards allowed).', 'initial-setup', 'initial-setup'),
  ('job.entities.job_rule.hints.event_subject', 'en-US', 'The NATS subject this rule listens to — when a module publishes an event on this subject the rule may fire. Pick a declared event or type any subject (wildcards allowed).', 'initial-setup', 'initial-setup'),
  ('job.entities.job_rule.hints.event_subject', 'it-IT', 'Il subject NATS che questa regola ascolta — quando un modulo pubblica un evento su questo subject la regola può scattare. Scegli un evento dichiarato o digita un subject qualsiasi (wildcard ammessi).', 'initial-setup', 'initial-setup'),
  ('job.entities.job_rule.hints.event_subject', 'de-DE', 'Das NATS-Subject, auf das diese Regel hört — wenn ein Modul ein Ereignis auf diesem Subject veröffentlicht, kann die Regel auslösen. Deklariertes Ereignis wählen oder ein beliebiges Subject eingeben (Wildcards erlaubt).', 'initial-setup', 'initial-setup'),
  ('job.entities.job_rule.hints.event_subject', 'fr-FR', 'Le sujet NATS que cette règle écoute — quand un module publie un événement sur ce sujet, la règle peut se déclencher. Choisir un événement déclaré ou saisir un sujet quelconque (jokers autorisés).', 'initial-setup', 'initial-setup'),
  ('job.entities.job_rule.hints.event_subject', 'es-ES', 'El asunto NATS que esta regla escucha — cuando un módulo publica un evento en este asunto, la regla puede dispararse. Elija un evento declarado o escriba cualquier asunto (comodines permitidos).', 'initial-setup', 'initial-setup'),
  ('job.entities.job_rule.hints.event_subject', 'pt-PT', 'O assunto NATS que esta regra escuta — quando um módulo publica um evento neste assunto, a regra pode disparar. Escolha um evento declarado ou digite qualquer assunto (coringas permitidos).', 'initial-setup', 'initial-setup'),
