  ('job.entities.job_rule.hints.filter_title', 'es-ES', 'Filtro', 'initial-setup', 'initial-setup'),
  ('job.entities.job_rule.hints.filter_title', 'pt-PT', 'Filtro', 'initial-setup', 'initial-setup'),
  ('job.entities.job_rule.hints.filter', 'en-GB', 'JSON conditions that must all match the event payload for the rule to fire — an array of `{ field, op, value }` entries evaluated against the event.', 'initial-setup', 'initial-setup'),
  ('job.entities.job_rule.hints.filter', 'en-US', 'JSON conditions that must all match the event payload for the rule to fire — an array of `{ field, op, value }` entries evaluated against the event.', 'initial-setup', 'initial-setup'),
  ('job.entities.job_rule.hints.filter', 'it-IT', 'Condizioni JSON che devono corrispondere tutte al payload dell''evento perché la regola scatti — un array di voci `{ field, op, value }` valutate sull''evento.', 'initial-setup', 'initial-setup'),
  ('job.entities.job_rule.hints.filter', 'de-DE', 'JSON-Bedingungen, die alle auf die Ereignis-Payload zutreffen müssen, damit die Regel auslöst — ein Array von `{ field, op, value }`-Einträgen.', 'initial-setup', 'initial-setup'),
  ('job.entities.job_rule.hints.filter', 'fr-FR', 'Conditions JSON qui doivent toutes correspondre au payload de l''événement pour que la règle se déclenche — un tableau d''entrées `{ field, op, value }`.', 'initial-setup', 'initial-setup'),
  ('job.entities.job_rule.hints.filter', 'es-ES', 'Condiciones JSON que deben coincidir todas con el payload del evento para que la regla se dispare — un array de entradas `{ field, op, value }`.', 'initial-setup', 'initial-setup'),
  ('job.entities.job_rule.hints.filter', 'pt-PT', 'Condições JSON que devem corresponder todas ao payload do evento para a regra disparar — um array de entradas `{ field, op, value }`.', 'initial-setup', 'initial-setup'),
  -- schedule_spec
  ('job.entities.job_rule.hints.schedule_spec_title', 'en-GB', 'Schedule', 'initial-setup', 'initial-setup'),
