  ('job.entities.job_rule.hints.schedule_spec_title', 'fr-FR', 'Planification', 'initial-setup', 'initial-setup'),
  ('job.entities.job_rule.hints.schedule_spec_title', 'es-ES', 'Programación', 'initial-setup', 'initial-setup'),
  ('job.entities.job_rule.hints.schedule_spec_title', 'pt-PT', 'Agendamento', 'initial-setup', 'initial-setup'),
  ('job.entities.job_rule.hints.schedule_spec', 'en-GB', 'When the rule fires — `@every <n><unit>` for intervals, `@at <timestamp>` for one-shot, or a 5-field cron expression. The assistant button builds one for you.', 'initial-setup', 'initial-setup'),
  ('job.entities.job_rule.hints.schedule_spec', 'en-US', 'When the rule fires — `@every <n><unit>` for intervals, `@at <timestamp>` for one-shot, or a 5-field cron expression. The assistant button builds one for you.', 'initial-setup', 'initial-setup'),
  ('job.entities.job_rule.hints.schedule_spec', 'it-IT', 'Quando la regola scatta — `@every <n><unit>` per intervalli, `@at <timestamp>` per esecuzione singola, o un''espressione cron a 5 campi. Il pulsante assistente ne costruisce una per te.', 'initial-setup', 'initial-setup'),
  ('job.entities.job_rule.hints.schedule_spec', 'de-DE', 'Wann die Regel auslöst — `@every <n><unit>` für Intervalle, `@at <timestamp>` für einmalig oder ein 5-Felder-Cron-Ausdruck. Die Assistenten-Schaltfläche erstellt einen für Sie.', 'initial-setup', 'initial-setup'),
  ('job.entities.job_rule.hints.schedule_spec', 'fr-FR', 'Quand la règle se déclenche — `@every <n><unit>` pour les intervalles, `@at <timestamp>` pour un tir unique, ou une expression cron à 5 champs. Le bouton assistant en construit une pour vous.', 'initial-setup', 'initial-setup'),
  ('job.entities.job_rule.hints.schedule_spec', 'es-ES', 'Cuándo se dispara la regla — `@every <n><unit>` para intervalos, `@at <timestamp>` para una vez, o una expresión cron de 5 campos. El botón asistente construye una por usted.', 'initial-setup', 'initial-setup'),
  ('job.entities.job_rule.hints.schedule_spec', 'pt-PT', 'Quando a regra dispara — `@every <n><unit>` para intervalos, `@at <timestamp>` para uma vez, ou uma expressão cron de 5 campos. O botão assistente constrói uma para você.', 'initial-setup', 'initial-setup'),
  -- target_subject
  ('job.entities.job_rule.hints.target_subject_title', 'en-GB', 'Destination subject', 'initial-setup', 'initial-setup'),
