  ('job.entities.job_rule.hints.target_subject_title', 'de-DE', 'Ziel-Subject', 'initial-setup', 'initial-setup'),
  ('job.entities.job_rule.hints.target_subject_title', 'fr-FR', 'Sujet de destination', 'initial-setup', 'initial-setup'),
  ('job.entities.job_rule.hints.target_subject_title', 'es-ES', 'Asunto de destino', 'initial-setup', 'initial-setup'),
  ('job.entities.job_rule.hints.target_subject_title', 'pt-PT', 'Assunto de destino', 'initial-setup', 'initial-setup'),
  ('job.entities.job_rule.hints.target_subject', 'en-GB', 'The `jobs.due.<lane>.<service>.<action>` subject the rule publishes to when it fires — where the scheduled job lands. The lane must match the execution context.', 'initial-setup', 'initial-setup'),
  ('job.entities.job_rule.hints.target_subject', 'en-US', 'The `jobs.due.<lane>.<service>.<action>` subject the rule publishes to when it fires — where the scheduled job lands. The lane must match the execution context.', 'initial-setup', 'initial-setup'),
  ('job.entities.job_rule.hints.target_subject', 'it-IT', 'Il subject `jobs.due.<lane>.<service>.<action>` su cui la regola pubblica quando scatta — dove atterra il job pianificato. La lane deve corrispondere al contesto di esecuzione.', 'initial-setup', 'initial-setup'),
  ('job.entities.job_rule.hints.target_subject', 'de-DE', 'Das `jobs.due.<lane>.<service>.<action>`-Subject, auf das die Regel beim Auslösen veröffentlicht — wo der geplante Job landet. Die Lane muss zum Ausführungskontext passen.', 'initial-setup', 'initial-setup'),
  ('job.entities.job_rule.hints.target_subject', 'fr-FR', 'Le sujet `jobs.due.<lane>.<service>.<action>` sur lequel la règle publie quand elle se déclenche — où atterrit le job planifié. La lane doit correspondre au contexte d''exécution.', 'initial-setup', 'initial-setup'),
  ('job.entities.job_rule.hints.target_subject', 'es-ES', 'El asunto `jobs.due.<lane>.<service>.<action>` sobre el que la regla publica cuando se dispara — donde aterriza el job programado. La lane debe coincidir con el contexto de ejecución.', 'initial-setup', 'initial-setup'),
  ('job.entities.job_rule.hints.target_subject', 'pt-PT', 'O assunto `jobs.due.<lane>.<service>.<action>` no qual a regra publica quando dispara — onde o job agendado aterrissa. A lane deve corresponder ao contexto de execução.', 'initial-setup', 'initial-setup'),
  -- execution_context
  ('job.entities.job_rule.hints.execution_context_title', 'en-GB', 'Execution context', 'initial-setup', 'initial-setup'),
  ('job.entities.job_rule.hints.execution_context_title', 'en-US', 'Execution context', 'initial-setup', 'initial-setup'),
  ('job.entities.job_rule.hints.execution_context_title', 'it-IT', 'Contesto di esecuzione', 'initial-setup', 'initial-setup'),
  ('job.entities.job_rule.hints.execution_context_title', 'de-DE', 'Ausführungskontext', 'initial-setup', 'initial-setup'),
  ('job.entities.job_rule.hints.execution_context_title', 'fr-FR', 'Contexte d''exécution', 'initial-setup', 'initial-setup'),
  ('job.entities.job_rule.hints.execution_context_title', 'es-ES', 'Contexto de ejecución', 'initial-setup', 'initial-setup'),
  ('job.entities.job_rule.hints.execution_context_title', 'pt-PT', 'Contexto de execução', 'initial-setup', 'initial-setup'),
  ('job.entities.job_rule.hints.execution_context', 'en-GB', '`user` runs the action as the triggering user (with their permissions); `system` runs with module privileges. Must match the lane in the destination subject.', 'initial-setup', 'initial-setup'),
  ('job.entities.job_rule.hints.execution_context', 'en-US', '`user` runs the action as the triggering user (with their permissions); `system` runs with module privileges. Must match the lane in the destination subject.', 'initial-setup', 'initial-setup'),
  ('job.entities.job_rule.hints.execution_context', 'it-IT', '`user` esegue l''azione come l''utente che ha innescato (con i suoi permessi); `system` con i privilegi del modulo. Deve corrispondere alla lane nel soggetto destinazione.', 'initial-setup', 'initial-setup'),
  ('job.entities.job_rule.hints.execution_context', 'de-DE', '`user` führt die Aktion als der auslösende Benutzer aus (mit dessen Berechtigungen); `system` mit Modulprivilegien. Muss zur Lane im Ziel-Subject passen.', 'initial-setup', 'initial-setup'),
  ('job.entities.job_rule.hints.execution_context', 'fr-FR', '`user` exécute l''action comme l''utilisateur déclencheur (avec ses permissions) ; `system` avec les privilèges du module. Doit correspondre à la lane du sujet de destination.', 'initial-setup', 'initial-setup'),
  ('job.entities.job_rule.hints.execution_context', 'es-ES', '`user` ejecuta la acción como el usuario que disparó (con sus permisos); `system` con privilegios del módulo. Debe coincidir con la lane del asunto de destino.', 'initial-setup', 'initial-setup'),
  ('job.entities.job_rule.hints.execution_context', 'pt-PT', '`user` executa a ação como o usuário que disparou (com suas permissões); `system` com privilégios do módulo. Deve corresponder à lane no assunto de destino.', 'initial-setup', 'initial-setup'),
  -- source_subject
  ('job.entities.job_rule.hints.source_subject_title', 'en-GB', 'Source subject', 'initial-setup', 'initial-setup'),
  ('job.entities.job_rule.hints.source_subject_title', 'en-US', 'Source subject', 'initial-setup', 'initial-setup'),
