  ('job.entities.job_rule.hints.source_subject_title', 'de-DE', 'Quell-Subject', 'initial-setup', 'initial-setup'),
  ('job.entities.job_rule.hints.source_subject_title', 'fr-FR', 'Sujet source', 'initial-setup', 'initial-setup'),
  ('job.entities.job_rule.hints.source_subject_title', 'es-ES', 'Asunto de origen', 'initial-setup', 'initial-setup'),
  ('job.entities.job_rule.hints.source_subject_title', 'pt-PT', 'Assunto de origem', 'initial-setup', 'initial-setup'),
  ('job.entities.job_rule.hints.source_subject', 'en-GB', 'Optional NATS subject the action reads its input payload from. Distinct from the event subject: the event TRIGGERS the rule, the source FEEDS it.', 'initial-setup', 'initial-setup'),
  ('job.entities.job_rule.hints.source_subject', 'en-US', 'Optional NATS subject the action reads its input payload from. Distinct from the event subject: the event TRIGGERS the rule, the source FEEDS it.', 'initial-setup', 'initial-setup'),
  ('job.entities.job_rule.hints.source_subject', 'it-IT', 'Subject NATS opzionale da cui l''azione legge il payload di input. Diverso dal soggetto evento: l''evento INNESCA la regola, la sorgente la ALIMENTA.', 'initial-setup', 'initial-setup'),
  ('job.entities.job_rule.hints.source_subject', 'de-DE', 'Optionales NATS-Subject, aus dem die Aktion ihre Eingabe-Payload liest. Anders als das Ereignis-Subject: das Ereignis LÖST die Regel aus, die Quelle SPEIST sie.', 'initial-setup', 'initial-setup'),
  ('job.entities.job_rule.hints.source_subject', 'fr-FR', 'Sujet NATS optionnel duquel l''action lit son payload d''entrée. Différent du sujet de l''événement : l''événement DÉCLENCHE la règle, la source l''ALIMENTE.', 'initial-setup', 'initial-setup'),
  ('job.entities.job_rule.hints.source_subject', 'es-ES', 'Asunto NATS opcional del que la acción lee su payload de entrada. Distinto del asunto del evento: el evento DISPARA la regla, el origen la ALIMENTA.', 'initial-setup', 'initial-setup'),
  ('job.entities.job_rule.hints.source_subject', 'pt-PT', 'Assunto NATS opcional do qual a ação lê seu payload de entrada. Diferente do assunto do evento: o evento DISPARA a regra, a origem a ALIMENTA.', 'initial-setup', 'initial-setup'),
  -- emitted-event description (EmitDecl.description_key)
  ('job.events.rules_changed.desc', 'en-GB', 'Fired when the job rule set changes — `jobs` domain, `ctl` control channel, `rules` resource, `changed` verb. The rules engine re-arms schedules on it.', 'initial-setup', 'initial-setup'),
  ('job.events.rules_changed.desc', 'en-US', 'Fired when the job rule set changes — `jobs` domain, `ctl` control channel, `rules` resource, `changed` verb. The rules engine re-arms schedules on it.', 'initial-setup', 'initial-setup'),
  ('job.events.rules_changed.desc', 'it-IT', 'Emesso quando l''insieme delle regole job cambia — `jobs` dominio, `ctl` canale di controllo, `rules` risorsa, `changed` verbo. Il motore delle regole ri-arma le pianificazioni.', 'initial-setup', 'initial-setup'),
  ('job.events.rules_changed.desc', 'de-DE', 'Wird ausgelöst, wenn sich die Job-Regelmenge ändert — `jobs` Domäne, `ctl` Steuerkanal, `rules` Ressource, `changed` Verb. Die Regel-Engine rüstet Zeitpläne neu auf.', 'initial-setup', 'initial-setup'),
  ('job.events.rules_changed.desc', 'fr-FR', 'Émis quand l''ensemble des règles de job change — `jobs` domaine, `ctl` canal de contrôle, `rules` ressource, `changed` verbe. Le moteur de règles ré-arme les planifications.', 'initial-setup', 'initial-setup'),
  ('job.events.rules_changed.desc', 'es-ES', 'Emitido cuando el conjunto de reglas de job cambia — `jobs` dominio, `ctl` canal de control, `rules` recurso, `changed` verbo. El motor de reglas rearma las programaciones.', 'initial-setup', 'initial-setup'),
  ('job.events.rules_changed.desc', 'pt-PT', 'Emitido quando o conjunto de regras de job muda — `jobs` domínio, `ctl` canal de controle, `rules` recurso, `changed` verbo. O motor de regras rearma os agendamentos.', 'initial-setup', 'initial-setup');
